function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function nav(){return `<aside class="sidebar"><div class="brand"><span class="brand-mark"></span>órbita<span style="font-size:10px;letter-spacing:1px;color:#7e8da9;margin-top:10px">CRM</span></div><div class="navgroup"><div class="nav-label">ESPAÇO COMERCIAL</div>${['Funil de vendas','Conversas','Agenda','Fluxo & decisões','Configurações','Simulador WhatsApp'].map((n,i)=>`<button class="navitem ${view===['kanban','inbox','calendar','flow','settings','simulator'][i]?'active':''}" data-view="${['kanban','inbox','calendar','flow','settings','simulator'][i]}">${icons[i]||icons[1]}${n}</button>`).join('')}</div><div class="sidebar-foot">FEITO PARA O SEU PROCESSO<br><b style="color:#c9d4e8">Uma conversa. Um próximo passo.</b><br><br>Desafio Opens · João Paulo</div></aside>`}
function render(){app.innerHTML=`<div class="shell">${nav()}<main class="workspace"><header class="topbar"><span class="breadcrumb">Operação comercial &nbsp; / &nbsp; ${esc({kanban:'Funil de vendas',inbox:'Conversas',calendar:'Agenda',flow:'Fluxo & decisões',settings:'Configurações',simulator:'Simulador WhatsApp'}[view])}</span><div class="top-actions"><span class="badge blue" id="connection">${demo?'Demonstração · dados ilustrativos':'Conectando…'}</span><button id="mode">${demo?'Conectar meu CRM':'Sair'}</button><span class="avatar">JP</span></div></header><section class="content" id="content"></section></main></div>`;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();window.scrollTo(0,0)});document.querySelector('#mode').onclick=()=>showLogin();renderView()}
function renderView(){const c=document.querySelector('#content');c.innerHTML=`<div class="heading"><div><h1>${({kanban:'Seu funil, em movimento',inbox:'O contexto vem junto',calendar:'Espaço para boas conversas',flow:'Da mensagem à oportunidade',settings:'Seu processo, suas regras',simulator:'Veja o atendimento acontecer'})[view]}</h1><p>CRM, atendimento e agenda em um só lugar.</p></div>${view==='kanban'?'<button class="primary" id="newlead">＋ Novo lead</button>':''}</div>${view==='kanban'?'<div class="metrics">'+[['Leads no funil','0','Todos os canais'],['Prontos para conversar','0','Qualificação explicável'],['Reuniões confirmadas','0','Agenda própria'],['Aguardando humano','0','Prioridade no atendimento']].map(x=>`<div class="metric"><div class="metric-title">${x[0]}</div><div class="metric-value">${x[1]}</div><small>${x[2]}</small></div>`).join('')+'</div><div class="toolbar"><input placeholder="Buscar por nome, empresa ou telefone" aria-label="Buscar lead"><select aria-label="Temperatura"><option>Todas as temperaturas</option></select><small class="right">Arraste os cartões entre etapas</small></div><div class="board">'+stages.map(x=>`<section class="column"><div class="col-head"><span><i style="--col:${x[2]}"></i>${x[1]}</span><span class="count">0</span></div><div class="empty">Nenhum lead nesta etapa</div></section>`).join('')+'</div>':'<div class="panel"><p class="muted">Preparando a operação…</p></div>'}`;}
